def g(sh: tuple | None = None, mid: tuple | None = None, hi: tuple | None = None, glob: tuple | None = None, blending: int | None = None, balance: int | None = None) -> dict:
    out: dict = {}
    for key, v in (("shadows", sh), ("midtones", mid), ("highlights", hi), ("global", glob)):
        if v:
            out[key] = {"hue": v[0], "sat": v[1], **({"lum": v[2]} if len(v) > 2 else {})}
    if blending is not None:
        out["blending"] = blending
    if balance is not None:
        out["balance"] = balance
    return out


def mix(**bands: tuple) -> dict:
    return {b: {k: v for k, v in zip(("hue", "sat", "lum"), t) if v} for b, t in bands.items()}


def P(group: str, name: str, description: str, tags: str, **settings) -> dict:
    return {"group": group, "name": name, "description": description, "tags": tags.split(), "settings": settings}


def A(group: str, name: str, description: str, tags: str, label: str, shapes: list[dict], adjust: dict) -> dict:
    return P(group, name, description, tags, masks=[{"id": 1, "name": label, "visible": True, "components": [{"shape": s, "op": "add"} for s in shapes], "adjust": adjust}])


def part(group: str, key: str, label: str) -> dict:
    return {"kind": group, "part": key, "label": label, "bitmap": f"adaptive-{key}"}


